// Builds src/catalogue.generated.ts (brand names only - no prices) from the Sunflow supplier catalogue workbook, so the
// panel / battery / inverter / EV charger brand suggestions in the CRM match what Sunflow actually buys.
//
// Usage: node scripts/import-brands.mjs [path-to-Sunflow_Supplier_Catalogue.xlsx]
//        (default: ../output/pylon-components/Sunflow_Supplier_Catalogue.xlsx)
// Run it again whenever the catalogue changes, then commit the regenerated file.
import { readFileSync, writeFileSync } from "node:fs";
import { inflateRawSync } from "node:zlib";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const file = path.resolve(process.argv[2] ?? path.join(here, "../../output/pylon-components/Sunflow_Supplier_Catalogue.xlsx"));

/** Some catalogue rows were scraped with the wrong "Brand" (a heading or product word). Fix or drop them here. */
const ALIAS = { ES: "Dyness", New: "Sigenergy" }; // "ES-DYS-Cygni BAT" rows are Dyness; "SigenStor BAT" rows are Sigenergy
const DROP = new Set(["Promotion", "SOL", "X280"]); // not brands: a sale label, an unidentified product line, a charger model code

/** Minimal zip reader (store + deflate) - enough for .xlsx. */
function unzip(buf) {
  let eocd = buf.length - 22;
  while (eocd >= 0 && buf.readUInt32LE(eocd) !== 0x06054b50) eocd--;
  if (eocd < 0) throw new Error("Not a zip / xlsx file");
  const count = buf.readUInt16LE(eocd + 10);
  let p = buf.readUInt32LE(eocd + 16);
  const files = new Map();
  for (let i = 0; i < count; i++) {
    const method = buf.readUInt16LE(p + 10), csize = buf.readUInt32LE(p + 20), nlen = buf.readUInt16LE(p + 28);
    const elen = buf.readUInt16LE(p + 30), clen = buf.readUInt16LE(p + 32), local = buf.readUInt32LE(p + 42);
    const name = buf.toString("utf8", p + 46, p + 46 + nlen);
    const lnlen = buf.readUInt16LE(local + 26), lelen = buf.readUInt16LE(local + 28);
    const data = buf.subarray(local + 30 + lnlen + lelen, local + 30 + lnlen + lelen + csize);
    files.set(name, method === 0 ? data : inflateRawSync(data));
    p += 46 + nlen + elen + clen;
  }
  return files;
}

const dec = (s) => s.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'");
const zip = unzip(readFileSync(file));
const text = (n) => (zip.has(n) ? zip.get(n).toString("utf8") : "");
const shared = [...text("xl/sharedStrings.xml").matchAll(/<si>([\s\S]*?)<\/si>/g)].map((m) =>
  dec([...m[1].matchAll(/<t[^>]*>([\s\S]*?)<\/t>/g)].map((x) => x[1]).join("")),
);
const rels = text("xl/_rels/workbook.xml.rels");

/** First column ("Brand") of every row below the header, for one sheet. */
function brandColumn(sheetName) {
  for (const m of text("xl/workbook.xml").matchAll(/<sheet [^>]*name="([^"]*)"[^>]*r:id="([^"]*)"/g)) {
    if (dec(m[1]) !== sheetName) continue;
    const rel = rels.match(new RegExp(`Id="${m[2]}"[^>]*Target="([^"]*)"|Target="([^"]*)"[^>]*Id="${m[2]}"`));
    const target = ((rel && (rel[1] || rel[2])) || "").replace(/^\/?(xl\/)?/, "");
    const out = [];
    let isHeader = true;
    for (const r of text("xl/" + target).matchAll(/<row [^>]*>([\s\S]*?)<\/row>/g)) {
      const c = r[1].match(/<c r="A\d+"([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/);
      if (!c) continue;
      const body = c[2] || "";
      const v = (body.match(/<v>([\s\S]*?)<\/v>/) || [])[1];
      const inline = (body.match(/<t[^>]*>([\s\S]*?)<\/t>/) || [])[1];
      const val = /t="s"/.test(c[1]) && v != null ? shared[+v] : inline != null ? dec(inline) : v != null ? dec(v) : "";
      if (isHeader) { isHeader = false; if (val !== "Brand") throw new Error(`"${sheetName}": first column is "${val}", expected "Brand"`); continue; }
      out.push(String(val));
    }
    return out;
  }
  throw new Error(`Sheet "${sheetName}" not found in ${file}`);
}

function clean(values) {
  const seen = new Map();
  for (let v of values) {
    v = v.replace(/\s+/g, " ").trim();
    if (!v || v.length > 30 || /[{}<>\n]|function|http/i.test(v)) continue; // scraped page code, not a brand
    v = ALIAS[v] ?? v;
    if (DROP.has(v)) continue;
    if (!seen.has(v.toLowerCase())) seen.set(v.toLowerCase(), v);
  }
  return [...seen.values()].sort((a, b) => a.localeCompare(b, "en", { sensitivity: "base" }));
}

const sheets = { panels: "Panels", inverters: "Inverters", batteries: "Batteries", evChargers: "EV Chargers" };
const result = Object.fromEntries(Object.entries(sheets).map(([key, sheet]) => [key, clean(brandColumn(sheet))]));

writeFileSync(
  path.resolve(here, "../src/catalogue.generated.ts"),
  `// Generated by scripts/import-brands.mjs from Sunflow_Supplier_Catalogue.xlsx. Brand names only - no prices. Do not edit by hand.\n` +
    `export const CATALOGUE_BRANDS = ${JSON.stringify(result, null, 2)} as const;\n`,
);
for (const [k, v] of Object.entries(result)) console.log(`${k}: ${v.length} brands - ${v.join(", ")}`);
